sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float2 center;
uniform float streak;

half4 main(float2 coord) {
    float2 c = center * size;
    float2 d = coord - c;
    float s = clamp(amount, 0.0, 1.9);
    float n = streak > 0.5 ? 128.0 : 48.0;
    float4 sum = float4(0.0);
    float2 e = d * (sqrt(size.x * size.y) / max(length(d), 0.001));
    for (int i = 0; i < 128; ++i) {
        if (float(i) >= n) break;
        float t = s * (float(i) / (n - 1.0) - 0.5);
        sum += float4(image.eval(streak > 0.5 ? coord + e * t : c + d * (1.0 + t)));
    }
    return half4(sum / n);
}
